<template>
	<div class="login_page">
		<div class="login_grid"></div>
		<div class="login_header">
			<div class="login_header_bg"></div>
		</div>

		<div class="login_main">
			<section class="login_intro">
				<h1>协同控制系统</h1>
				<div class="intro_line"></div>
			</section>

			<section class="login_card">
				<div class="login_card_title">
					<span>系统登录</span>
					<small>LOGIN</small>
				</div>

				<el-form class="login_form" @submit.prevent="handleLogin">
					<div class="form_item">
						<label>账号</label>
						<el-input v-model="form.username" placeholder="请输入账号" clearable />
					</div>
					<div class="form_item">
						<label>密码</label>
						<el-input v-model="form.password" placeholder="请输入密码" type="password" show-password />
					</div>
					<div class="error_text" :class="{ show: errorText }">{{ errorText }}</div>
					<button class="login_button" type="submit">进入系统</button>
				</el-form>

			</section>
		</div>
	</div>
</template>

<script setup>
import { reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { login } from '@/utils/auth'

const route = useRoute()
const router = useRouter()
const errorText = ref('')
const form = reactive({
	username: '',
	password: ''
})

const handleLogin = () => {
	errorText.value = ''

	if (!form.username || !form.password) {
		errorText.value = '请输入账号和密码'
		return
	}

	if (!login(form.username, form.password)) {
		errorText.value = '账号或密码错误'
		return
	}

	router.replace(route.query.redirect || '/welcome')
}
</script>

